package fraymus.workspace;

import org.json.*;
import javax.imageio.*;
import java.awt.image.BufferedImage;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.function.*;

/** Data-only evaluation. The predictor receives pixels and first-frame initialization, never later truth. */
public final class TrackingEvaluation {
    static final String BASELINE="rgb-v1",CANDIDATE="adaptive-v2";
    static ImageTracker tracker(String profile,String id,String label,BufferedImage image,PixelTracker.Box box){return switch(profile){case BASELINE->new PixelTracker(id,label,image,box,true);case CANDIDATE->new AdaptiveTracker(id,label,image,box);default->throw new IllegalArgumentException("Unknown installed tracker profile");};}
    static String codeHash(String profile) throws Exception {Class<?> type=switch(profile){case BASELINE->PixelTracker.class;case CANDIDATE->AdaptiveTracker.class;default->throw new IllegalArgumentException("Unknown tracker");};try(var in=type.getResourceAsStream(type.getSimpleName()+".class")){return PerceptionStore.hash(in.readAllBytes());}}
    static byte[] data(JSONObject frame,String key) throws Exception {byte[] b=Base64.getDecoder().decode(frame.getString(key));if(b.length>1_000_000||!PerceptionStore.hash(b).equals(frame.getString(key+"Sha256")))throw new IllegalArgumentException("Frame hash or byte budget changed: "+key);return b;}
    static BufferedImage image(byte[] b,boolean mask) throws Exception {try(var input=ImageIO.createImageInputStream(new ByteArrayInputStream(b))){var readers=ImageIO.getImageReaders(input);if(!readers.hasNext())throw new IllegalArgumentException("Unsupported frame image");var reader=readers.next();try{reader.setInput(input);if(!Set.of("JPEG","JPG","PNG").contains(reader.getFormatName().toUpperCase(Locale.ROOT))||mask&&!reader.getFormatName().equalsIgnoreCase("png"))throw new IllegalArgumentException("JPEG/PNG frames and indexed PNG masks required");int w=reader.getWidth(0),h=reader.getHeight(0);if(w<24||h<24||w>1024||h>1024||w*(long)h>786432)throw new IllegalArgumentException("Bounded frame dimensions required");var out=reader.read(0);if(mask&&out.getRaster().getNumBands()!=1)throw new IllegalArgumentException("Indexed single-channel object mask required");return out;}finally{reader.dispose();}}}
    static PixelTracker.Box truth(BufferedImage mask,int object){int x0=mask.getWidth(),y0=mask.getHeight(),x1=-1,y1=-1;var r=mask.getRaster();for(int y=0;y<mask.getHeight();y++)for(int x=0;x<mask.getWidth();x++)if(r.getSample(x,y,0)==object){x0=Math.min(x,x0);y0=Math.min(y,y0);x1=Math.max(x,x1);y1=Math.max(y,y1);}return x1<0?null:new PixelTracker.Box(x0/(double)mask.getWidth(),y0/(double)mask.getHeight(),(x1-x0+1.)/mask.getWidth(),(y1-y0+1.)/mask.getHeight());}
    static JSONObject validate(JSONObject pack) throws Exception {SpatialScene.keys(pack,"schema","title","sequence","split","objectId","source","license","notes","frames");if(!pack.getString("schema").equals("fraynix-tracking-sequence-v1"))throw new IllegalArgumentException("Tracking sequence schema required");for(String key:List.of("title","sequence","source","license","notes"))if(pack.getString(key).length()>1000)throw new IllegalArgumentException("Source description budget exceeded");if(pack.getString("title").isBlank()||pack.getString("sequence").isBlank()||pack.getString("license").isBlank())throw new IllegalArgumentException("Declare sequence, title and license");if(!Set.of("development","evaluation").contains(pack.getString("split")))throw new IllegalArgumentException("Declare development or evaluation split");int object=pack.getInt("objectId");if(object<1||object>254)throw new IllegalArgumentException("Object ID1..254 required");var frames=pack.getJSONArray("frames");if(frames.length()<5||frames.length()>128)throw new IllegalArgumentException("Choose5..128 frames");int previous=-1,w=0,h=0;long bytes=0;var hashes=new HashSet<String>();for(int i=0;i<frames.length();i++){var f=frames.getJSONObject(i);SpatialScene.keys(f,"sourceFrame","imageName","maskName","imageSha256","maskSha256","image","mask");int ordinal=f.getInt("sourceFrame");if(ordinal<=previous)throw new IllegalArgumentException("Source ordinals must strictly increase");previous=ordinal;for(String key:List.of("imageName","maskName"))if(f.getString(key).length()>500)throw new IllegalArgumentException("Source name budget");byte[] pixels=data(f,"image"),annotation=data(f,"mask");bytes+=pixels.length+annotation.length;if(bytes>24_000_000)throw new IllegalArgumentException("Sequence exceeds24 MB");if(!hashes.add(f.getString("imageSha256")))throw new IllegalArgumentException("Duplicate source image in a sequence");var image=image(pixels,false);var mask=image(annotation,true);if(i==0){w=image.getWidth();h=image.getHeight();if(truth(mask,object)==null)throw new IllegalArgumentException("First frame needs a reference object");}if(image.getWidth()!=w||image.getHeight()!=h||mask.getWidth()!=w||mask.getHeight()!=h)throw new IllegalArgumentException("Consistent image/mask dimensions required");}return new JSONObject().put("width",w).put("height",h).put("frames",frames.length()).put("bytes",bytes);}
    static JSONObject evaluate(JSONObject pack,String profile,BooleanSupplier cancelled,IntConsumer progress) throws Exception {var frames=pack.getJSONArray("frames");var first=frames.getJSONObject(0);var initial=image(data(first,"image"),false);var initialBox=truth(image(data(first,"mask"),true),pack.getInt("objectId"));if(initialBox==null)throw new IllegalArgumentException("First frame reference is absent");ImageTracker tracker=tracker(profile,"research-object",pack.getString("sequence"),initial,initialBox);var results=new JSONArray();for(int i=1;i<frames.length();i++){if(cancelled.getAsBoolean())throw new InterruptedException("Evaluation cancelled");var f=frames.getJSONObject(i);long start=System.nanoTime();var pixels=image(data(f,"image"),false);var prediction=tracker.update(pixels);double elapsed=(System.nanoTime()-start)/1e6;var reference=truth(image(data(f,"mask"),true),pack.getInt("objectId"));var predicted=prediction.isNull("box")?null:PixelTracker.Box.from(prediction.getJSONArray("box"));double iou=reference==null||predicted==null?0:PixelTracker.iou(reference,predicted);results.put(new JSONObject().put("ordinal",i).put("sourceFrame",f.getInt("sourceFrame")).put("imageSha256",f.getString("imageSha256")).put("maskSha256",f.getString("maskSha256")).put("reference",reference==null?JSONObject.NULL:reference.json()).put("prediction",prediction).put("iou",iou).put("processingMillis",elapsed));progress.accept(i);}
        return new JSONObject().put("profile",profile).put("codeSha256",codeHash(profile)).put("sequence",pack.getString("sequence")).put("split",pack.getString("split")).put("initialization",new JSONObject().put("sourceFrame",first.getInt("sourceFrame")).put("reference",initialBox.json()).put("scored",false)).put("frames",results).put("metrics",metrics(results));}
    static JSONObject metrics(JSONArray frames){double sum=0;int half=0,lost=0,low=0,reacquired=0,absent=0;var latency=new double[frames.length()];for(int i=0;i<frames.length();i++){var f=frames.getJSONObject(i);double overlap=f.getDouble("iou");RampDefinition.range(overlap,0,1,"reference overlap");sum+=overlap;if(overlap>=.5)half++;var p=f.getJSONObject("prediction");if(p.isNull("box"))lost++;else if(overlap<.1)low++;if(p.getString("status").equals("reacquired"))reacquired++;if(f.isNull("reference"))absent++;latency[i]=f.getDouble("processingMillis");}Arrays.sort(latency);int n=frames.length();return new JSONObject().put("scoredFrames",n).put("meanIou",sum/Math.max(1,n)).put("iouHalfFraction",half/(double)Math.max(1,n)).put("lowOverlapVisiblePredictions",low).put("lost",lost).put("reacquired",reacquired).put("referenceAbsentFrames",absent).put("medianProcessingMillis",n==0?0:latency[n/2]).put("p95ProcessingMillis",n==0?0:latency[Math.min(n-1,(int)Math.ceil(n*.95)-1)]).put("latencyScope","JPEG/PNG decode plus CPU tracking; excludes browser capture, network and LLM. Initialization excluded from scored frames.");}
    public static void main(String[] args) throws Exception {if(args.length!=2)throw new IllegalArgumentException("Usage: TrackingEvaluation pack.ftrack.json output.json");var pack=new JSONObject(Files.readString(Path.of(args[0])));validate(pack);var out=new JSONObject();for(String profile:List.of(BASELINE,CANDIDATE))out.put(profile,evaluate(pack,profile,()->false,i->{}));Files.writeString(Path.of(args[1]),out.toString(2));for(String profile:out.keySet())System.out.println(profile+" "+out.getJSONObject(profile).getJSONObject("metrics"));}
}
